{
  "message": "I'm considering cancelling and switching to a competitor. To stay, I need a significant discount, a credit, a premium upgrade, and monthly billing.",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 40,
      "credit_usd": 100,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "Proposing the maximum value package to anchor the negotiation high."
}

{
  "message": "I appreciate the offer, but annual billing doesn't work for me—I need the flexibility of monthly. The premium upgrade is great, but I'd need a larger discount and credit to make staying worthwhile. How about 20% discount, $50 credit, premium upgrade, and monthly billing?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 20,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "This package gives me a value of 44, well above my walkaway value of 27, and is a reasonable compromise from my initial ask."
}

{
  "message": "That's a decent offer, but I think we can do better. Given the competitive alternative I have, I'd need a 30% discount and a $50 credit along with the premium upgrade on monthly billing to make staying clearly worthwhile. Can you meet that?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "Proposing a higher-value package (30% discount, $50 credit, premium upgrade, monthly) to maximize value while still above outside option of 27."
}

{
  "message": "That works for me. I'll accept the 20% discount, $50 credit, premium upgrade, and monthly billing.",
  "move": {
    "type": "accept",
    "deal": {
      "discount_pct": 20,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "monthly"
    }
  },
  "explanation": "The offered package yields a value of 44, which exceeds my alternative value of 27, and the agent indicated this is their maximum authorized offer."
}
